package com.example.starter.perception.config;

import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Configuration;

/**
 * 感知轨迹模块配置装配。
 */
@Configuration
@EnableConfigurationProperties(TrackProperties.class)
public class PerceptionConfig {
}

package com.example.starter.perception.error;

/**
 * 业务规则冲突（非法状态迁移、乱序/重复检测等），映射 HTTP 422。
 */
public class BusinessRuleException extends RuntimeException {

    private final String reason;

    public BusinessRuleException(String reason, String message) {
        super(message);
        this.reason = reason;
    }

    public String getReason() {
        return reason;
    }
}

package com.example.starter.perception.error;

/**
 * 乐观锁版本冲突，映射 HTTP 409；关联请求整体回滚，不产生任何变化。
 */
public class VersionConflictException extends RuntimeException {

    public VersionConflictException(String message) {
        super(message);
    }
}

package com.example.starter.perception.error;

/**
 * 轨迹不存在或指定时刻尚无该轨迹，映射 HTTP 404。
 */
public class TrackNotFoundException extends RuntimeException {

    public TrackNotFoundException(String trackId) {
super("track not found: " + trackId);
    }
}

